create role anon nologin; create role authenticated nologin;
create schema auth; create schema private;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.actor',true),'')::uuid$$;
create function private.require_reauthentication_session() returns uuid language sql as $$select auth.uid()$$;
create function private.account_access_allowed() returns boolean language sql stable as $$select auth.uid() is not null$$;
create function private.has_company_feature(uuid,text) returns boolean language sql stable as $$select true$$;
create table public.companies(id uuid primary key);
create table public.company_members(company_id uuid,user_id uuid,role text);
create table public.workers(id uuid primary key,company_id uuid,affiliation text,name text,role text,phone text,employee_number text,department text,hire_date date,status text,user_id uuid,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.worker_personnel_profiles(worker_id uuid primary key,company_id uuid,blood_type text,address text,emergency_name text,emergency_relation text,emergency_phone text,emergency_address text,family_composition text,created_by uuid,updated_by uuid,updated_at timestamptz);
create table public.worker_family_members(id uuid default gen_random_uuid(),company_id uuid,worker_id uuid,name text,relation text,birth_date date,is_dependent boolean,created_by uuid,updated_by uuid);
create table public.worker_personnel_approvers(company_id uuid,user_id uuid);
create table public.worker_personnel_change_requests(id uuid primary key default gen_random_uuid(),company_id uuid,worker_id uuid,requested_by uuid,proposed jsonb,required_approvals int,status text default 'pending',resolved_at timestamptz);
create table public.worker_personnel_change_approvals(request_id uuid,approver_user_id uuid,decision text,unique(request_id,approver_user_id));
create table public.app_notifications(company_id uuid,recipient_user_id uuid,kind text,title text,body text,action_key text,action_id uuid);
create function private.can_edit_worker_personnel(p uuid) returns boolean language sql stable as $$select private.account_access_allowed() and exists(select 1 from public.workers w join public.company_members m on m.company_id=w.company_id where w.id=p and m.user_id=auth.uid() and m.role in ('owner','admin','manager'))$$;
create function private.personnel_view_allowed(p uuid) returns boolean language sql stable as $$select private.account_access_allowed() and exists(select 1 from public.company_members where company_id=p and user_id=auth.uid() and role in ('owner','admin','viewer','manager'))$$;
create function private.is_worker_personnel_approver(p uuid) returns boolean language sql stable as $$select exists(select 1 from public.worker_personnel_approvers where company_id=p and user_id=auth.uid())$$;
